    "ft.sec.pub":"Sector públic","ft.sec.sal":"Salut","ft.sec.tur":"Turisme","ft.sec.edu":"Educació","ft.sec.b2b":"B2B","ft.sec.leg":"Legal / Finances",
    "ft.tec.rag":"RAG","ft.tec.ag":"Agents","ft.tec.ch":"Conversacional","ft.tec.dt":"Dades","ft.tec.md":"Models","ft.tec.cp":"Compliance",
